        endHeightInsertionHint0: 0,
        endHeightInsertionHint1: 0
    });

    // This may revert unexpectedly due to the conservative originalAdd0 check
    fixedPoolType.addLiquidity(poolId, lp, posId, abi.encode(params));
}

